// Hand-written scenes and motion transitions for scripts/snapshot/main.cjs.
// The per-setting scenes are in scenes.settings.mjs (generated by gen-scenes.mjs).
//
// A scene:
//   name        file name of the capture
//   window      widget | settings | changelog | changelog-past | setup | update | versions
//   width       card width (window = width + 44); default per window
//   size        [w, h] fixed window size (fullscreen); otherwise the height follows the card
//   fsFrom      [x, y] where the widget's window sits on that screen before fullscreen (default: top right)
//   settings    { settingName: value } on top of the defaults (src/settings.ts names)
//   storage     { rawStorageKey: value } for state.* keys etc.
//   fake        deep-merged onto fixtures/fake-state.json ({ state, responses, noEvent })
//   steps       interaction ops, in order (see main.cjs: wait, move, moveOut, click, down, up,
//               type, wheel, emit, state)
//   maskSelectors  elements whose box gets the sung-line tolerance in the diff (default below)
//   settle      ms of virtual time before the steps (default 4000)
// A motion adds `timeline: [{ t, ...op }]` (t in ms after the trigger), `frames`, `fromLoad`.

const PLAYING = { state: { playing: true, status: "Playing" } };
const aa = { op: "click", selector: '.ctrl-aa[aria-label="Lyrics"]' };
const lyrics = { lyricsOnLaunch: true };
const hover = { op: "move", selector: ".widget" };
const nav = (n) => ({ op: "click", selector: `.st-nav-item:nth-child(${n})` });
const CATS = ["lyrics", "text", "languages", "highlight", "glass", "header", "controls", "album", "fun", "fullscreen", "behavior", "app"];
const release = (version, date, flavors, notes) => ({ version, date, notes, legacy: false, flavors });

